package com.freshmart.operations;

import com.freshmart.catalog.*;
import com.freshmart.audit.SafeAuditText;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import static com.freshmart.operations.OperationsModels.*;

/** Explicit bound SQL; all business writes share the caller's Spring transaction. */
@Repository
public class OperationsMapper {
 private final JdbcTemplate db;
 public OperationsMapper(JdbcTemplate db){this.db=db;}
 private static Instant instant(ResultSet r,String key)throws SQLException{var value=r.getTimestamp(key);return value==null?null:value.toInstant();}
 private static ProductRow product(ResultSet r,int n)throws SQLException{return new ProductRow(r.getString("product_id"),r.getString("spu_code"),r.getString("category_id"),r.getString("name"),r.getString("description"),r.getString("origin"),r.getString("storage"),r.getString("image_url"),r.getString("status"),r.getLong("version"));}
 private static SkuRow sku(ResultSet r,int n)throws SQLException{return new SkuRow(r.getString("sku_id"),r.getString("sku_code"),r.getString("product_id"),r.getString("name"),r.getString("unit_label"),r.getString("base_unit"),r.getString("price_mode"),(Long)r.getObject("price_unit_gram"),r.getLong("price"),r.getLong("member_price"),r.getString("image_url"),r.getString("status"),r.getLong("version"));}
 private static BatchRow batch(ResultSet r,int n)throws SQLException{return new BatchRow(r.getString("batch_id"),r.getString("batch_no"),r.getString("sku_id"),r.getString("base_unit"),r.getLong("on_hand"),r.getLong("reserved"),r.getLong("quarantined"),r.getString("lifecycle_status"),instant(r,"effective_produced_at"),instant(r,"expires_at"),instant(r,"received_at"),r.getLong("version"));}
 private static Policies policies(ResultSet r,int n)throws SQLException{return new Policies(r.getLong("freight_amount"),r.getLong("free_shipping_threshold_amount"),r.getInt("near_expiry_days"),r.getInt("near_expiry_discount_basis_points"),r.getLong("newcomer_coupon_amount"),r.getLong("newcomer_coupon_min_goods_amount"),r.getLong("version"));}
 private static <T>T first(List<T> rows){return rows.isEmpty()?null:rows.getFirst();}
 public ProductRow product(String id,boolean lock){return first(db.query("SELECT * FROM fm_product WHERE product_id=?"+(lock?" FOR UPDATE":""),OperationsMapper::product,id));}
 public List<ProductRow> products(String status,int size,long offset){return status==null?db.query("SELECT * FROM fm_product ORDER BY product_id LIMIT ? OFFSET ?",OperationsMapper::product,size,offset):db.query("SELECT * FROM fm_product WHERE status=? ORDER BY product_id LIMIT ? OFFSET ?",OperationsMapper::product,status,size,offset);}
 public long productCount(String status){return status==null?db.queryForObject("SELECT COUNT(*) FROM fm_product",Long.class):db.queryForObject("SELECT COUNT(*) FROM fm_product WHERE status=?",Long.class,status);}
 public boolean categoryEnabled(String id){return db.queryForObject("SELECT COUNT(*) FROM fm_category WHERE category_id=? AND enabled=TRUE",Long.class,id)>0;}
 public void insertProduct(ProductRow p,Instant now){db.update("INSERT INTO fm_product(product_id,spu_code,category_id,name,description,origin,storage,image_url,status,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,0,?,?)",p.productId(),p.spuCode(),p.categoryId(),p.name(),p.description(),p.origin(),p.storage(),p.imageUrl(),p.status(),Timestamp.from(now),Timestamp.from(now));}
 public int updateProduct(ProductRow p,Instant now){return db.update("UPDATE fm_product SET category_id=?,name=?,description=?,origin=?,storage=?,image_url=?,status=?,version=version+1,updated_at=? WHERE product_id=? AND version=?",p.categoryId(),p.name(),p.description(),p.origin(),p.storage(),p.imageUrl(),p.status(),Timestamp.from(now),p.productId(),p.version());}
 public SkuRow sku(String id,boolean lock){return first(db.query("SELECT * FROM fm_sku WHERE sku_id=?"+(lock?" FOR UPDATE":""),OperationsMapper::sku,id));}
 public List<SkuRow> skus(String product){return db.query("SELECT * FROM fm_sku WHERE product_id=? ORDER BY sku_id",OperationsMapper::sku,product);}
 public long skuCodeCount(String code,String except){return db.queryForObject("SELECT COUNT(*) FROM fm_sku WHERE sku_code=? AND sku_id<>?",Long.class,code,except);}
 public void insertSku(SkuRow s,Instant now){db.update("INSERT INTO fm_sku(sku_id,sku_code,product_id,name,unit_label,base_unit,price_mode,price_unit_gram,price,member_price,image_url,status,version,estimated_gram_per_unit,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,0,?,?,?)",s.skuId(),s.skuCode(),s.productId(),s.name(),s.unitLabel(),s.baseUnit(),s.priceMode(),s.priceUnitGram(),s.price(),s.memberPrice(),s.imageUrl(),s.status(),s.priceUnitGram()==null?500:s.priceUnitGram(),Timestamp.from(now),Timestamp.from(now));}
 public int updateSku(SkuRow s,Instant now){return db.update("UPDATE fm_sku SET sku_code=?,name=?,unit_label=?,base_unit=?,price_mode=?,price_unit_gram=?,price=?,member_price=?,image_url=?,version=version+1,updated_at=? WHERE sku_id=? AND version=?",s.skuCode(),s.name(),s.unitLabel(),s.baseUnit(),s.priceMode(),s.priceUnitGram(),s.price(),s.memberPrice(),s.imageUrl(),Timestamp.from(now),s.skuId(),s.version());}
 public long skuBatchCount(String id){return db.queryForObject("SELECT COUNT(*) FROM fm_inventory_batch WHERE sku_id=?",Long.class,id);}
 public long batchNoCount(String sku,String no){return db.queryForObject("SELECT COUNT(*) FROM fm_inventory_batch WHERE sku_id=? AND batch_no=?",Long.class,sku,no);}
 private static final String BATCH="SELECT b.*,s.base_unit,b.produced_at AS effective_produced_at FROM fm_inventory_batch b JOIN fm_sku s ON s.sku_id=b.sku_id";
 public BatchRow batch(String id,boolean lock){return first(db.query(BATCH+" WHERE b.batch_id=?"+(lock?" FOR UPDATE":""),OperationsMapper::batch,id));}
 public List<BatchRow> skuBatches(String sku){return db.query(BATCH+" WHERE b.sku_id=? AND b.lifecycle_status='NORMAL' AND b.on_hand-b.reserved-b.quarantined>0 ORDER BY b.expires_at,b.batch_id",OperationsMapper::batch,sku);}
 public List<BatchRow> skuBatches(List<String> skus){if(skus.isEmpty())return List.of();String marks=String.join(",",Collections.nCopies(skus.size(),"?"));return db.query(BATCH+" WHERE b.sku_id IN ("+marks+") AND b.lifecycle_status='NORMAL' AND b.on_hand-b.reserved-b.quarantined>0 ORDER BY b.expires_at,b.batch_id",OperationsMapper::batch,skus.toArray());}
 private record Filter(String sql,Object[] values){}
 private Filter batchFilter(String sku,String lifecycle,String freshness,Instant now,Instant near){var sql=new StringBuilder(" WHERE 1=1");var values=new ArrayList<Object>();if(sku!=null){sql.append(" AND b.sku_id=?");values.add(sku);}if(lifecycle!=null){sql.append(" AND b.lifecycle_status=?");values.add(lifecycle);}if(freshness!=null){switch(freshness){case "EXPIRED"->{sql.append(" AND b.expires_at<=?");values.add(Timestamp.from(now));}case "NEAR_EXPIRY"->{sql.append(" AND b.expires_at>? AND b.expires_at<=?");values.add(Timestamp.from(now));values.add(Timestamp.from(near));}default->{sql.append(" AND b.expires_at>?");values.add(Timestamp.from(near));}}}return new Filter(sql.toString(),values.toArray());}
 public long batchCount(String sku,String lifecycle,String freshness,Instant now,Instant near){var f=batchFilter(sku,lifecycle,freshness,now,near);return db.queryForObject("SELECT COUNT(*) FROM fm_inventory_batch b"+f.sql(),Long.class,f.values());}
 public List<BatchRow> batches(String sku,String lifecycle,String freshness,Instant now,Instant near,int size,long offset){var f=batchFilter(sku,lifecycle,freshness,now,near);var args=new ArrayList<>(Arrays.asList(f.values()));args.add(size);args.add(offset);return db.query(BATCH+f.sql()+" ORDER BY b.expires_at,b.batch_id LIMIT ? OFFSET ?",OperationsMapper::batch,args.toArray());}
 public void insertBatch(BatchRow b,Instant now){db.update("INSERT INTO fm_inventory_batch(batch_id,sku_id,batch_no,warehouse_id,received_at,produced_at,expires_at,lifecycle_status,on_hand,reserved,quarantined,version,created_at,updated_at) VALUES(?,?,?,'warehouse-main',?,?,?,'NORMAL',?,0,0,0,?,?)",b.batchId(),b.skuId(),b.batchNo(),Timestamp.from(b.receivedAt()),Timestamp.from(b.producedAt()),Timestamp.from(b.expiresAt()),b.onHand(),Timestamp.from(now),Timestamp.from(now));}
 public int updateBatch(BatchRow b,Instant now){return db.update("UPDATE fm_inventory_batch SET on_hand=?,reserved=?,quarantined=?,lifecycle_status=?,version=version+1,updated_at=? WHERE batch_id=? AND version=?",b.onHand(),b.reserved(),b.quarantined(),b.lifecycle(),Timestamp.from(now),b.batchId(),b.version());}
 public void movement(String id,String batch,String type,long hand,long reserved,long quarantine,String reason,String actor,Instant now){db.update("INSERT INTO fm_inventory_movement(movement_id,order_id,allocation_id,batch_id,type,on_hand_delta,reserved_delta,quarantined_delta,reason,actor_id,created_at) VALUES(?,NULL,NULL,?,?,?,?,?,?,?,?)",id,batch,type,hand,reserved,quarantine,reason,actor,Timestamp.from(now));}
 private Filter movementFilter(String batch,String order,boolean finance){var sql=new StringBuilder(" WHERE 1=1");var args=new ArrayList<Object>();if(finance)sql.append(" AND m.order_id IS NOT NULL");if(batch!=null){sql.append(" AND m.batch_id=?");args.add(batch);}if(order!=null){sql.append(" AND m.order_id=?");args.add(order);}return new Filter(sql.toString(),args.toArray());}
 public long movementCount(String batch,String order,boolean finance){var f=movementFilter(batch,order,finance);return db.queryForObject("SELECT COUNT(*) FROM fm_inventory_movement m"+f.sql(),Long.class,f.values());}
 public List<Movement> movements(String batch,String order,boolean finance,int size,long offset){var f=movementFilter(batch,order,finance);var args=new ArrayList<>(Arrays.asList(f.values()));args.add(size);args.add(offset);return db.query("SELECT m.*,b.sku_id FROM fm_inventory_movement m JOIN fm_inventory_batch b ON b.batch_id=m.batch_id"+f.sql()+" ORDER BY m.created_at DESC,m.movement_id DESC LIMIT ? OFFSET ?",(r,n)->new Movement(r.getString("movement_id"),r.getString("batch_id"),r.getString("sku_id"),r.getString("order_id"),r.getString("type"),r.getLong("on_hand_delta"),r.getLong("reserved_delta"),r.getLong("quarantined_delta"),r.getString("reason"),r.getString("actor_id"),instant(r,"created_at").toString()),args.toArray());}
 public Policies policies(boolean lock){return first(db.query("SELECT * FROM fm_business_policy WHERE policy_id='STORE'"+(lock?" FOR UPDATE":""),OperationsMapper::policies));}
 public int updatePolicies(Policies p,Instant now){return db.update("UPDATE fm_business_policy SET freight_amount=?,free_shipping_threshold_amount=?,near_expiry_days=?,near_expiry_discount_basis_points=?,newcomer_coupon_amount=?,newcomer_coupon_min_goods_amount=?,version=version+1,effective_at=? WHERE policy_id='STORE' AND version=?",p.freightAmount(),p.freeShippingThresholdAmount(),p.nearExpiryDays(),p.nearExpiryDiscountBasisPoints(),p.newcomerCouponAmount(),p.newcomerCouponMinGoodsAmount(),Timestamp.from(now),p.version());}
 public void updateNewcomer(Policies p){db.update("UPDATE fm_coupon_campaign SET discount_amount=CASE WHEN ?>0 THEN ? ELSE discount_amount END,min_goods_amount=?,enabled=?,version=version+1 WHERE campaign_id='NEW_MEMBER_V1'",p.newcomerCouponAmount(),p.newcomerCouponAmount(),p.newcomerCouponMinGoodsAmount(),p.newcomerCouponAmount()>0);}
 public int updateSlot(String id,SlotUpdate in){return db.update("UPDATE fm_delivery_slot SET capacity=?,cutoff_at=?,enabled=?,version=version+1 WHERE slot_id=? AND version=? AND used<=?",in.capacity(),Timestamp.from(in.cutoffAt()),in.enabled(),id,in.version(),in.capacity());}
 public void audit(String id,String actor,String operation,String type,String resource,String reason,String before,String after,String trace,Instant now,String roles,String outcome){db.update("INSERT INTO fm_audit_event(event_id,actor_id,operation,resource_type,resource_id,reason,before_summary,after_summary,trace_id,created_at,actor_roles_snapshot,outcome) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id,actor,operation,type,resource,SafeAuditText.redact(reason),before,after,trace,Timestamp.from(now),roles,outcome);}
}
